def fit(q, h):
    diagnostics = []
    try:
        ss, recipe = catfix_segments(q, h, 'poly', max(1., .02*max(h)))
        assert len(ss) == 1
        s = ss[0].copy()
        delta = [h[0]-s[0, 1], h[-1]-s[-1, 1]]
        s[:, 1] += np.linspace(*delta, 4)
        s[0, 1], s[-1, 1] = h[0], h[-1]
        ok, ck = float_checks([s], q, h)
        diagnostics.append({'method': 'CATFIX poly affine endpoint correction', 'checks': ck})
        if ok and not ck['significant_inflection_segments']:
            return [s], {'method': 'CATFIX_SINGLE_POLY_AFFINE_ENDPOINTS', 'CATFIX_call': recipe,
                         'endpoint_correction': list(map(float, delta)), 'unused_diagnostics': diagnostics}
    except ValueError as e:
        diagnostics.append({'CATFIX_poly_class_limit': str(e), 'not_general_impossibility': True})
    # Original 2% bounds; prefer concave natural C2 if whole polynomial was unsuitable.
    # Bernstein monotonic bounds are a search constraint, never stated as a
    # necessary universal condition. Final whole-domain derivative is proven.
    for ninner in range(1, len(q)-1):
        candidates = []
        for ii in itertools.combinations(range(1, len(q)-1), ninner):
            inds = [0, *ii, len(q)-1]
            xs = q[inds]
            hh = np.zeros(len(xs)); hh[[0, -1]] = h[[0, -1]]
            base, _ = catfix_segments(xs, hh)
            basis = []
            for j in range(ninner):
                hv = np.zeros(len(xs)); hv[j+1] = 1
                basis.append(catfix_segments(xs, hv)[0])
            A, B = [], []
            for Q, H, T in zip(q, h, np.maximum(1., h*.02)):
                k = max(0, min(np.searchsorted(xs, Q, side='right')-1, len(xs)-2))
                t = (Q-xs[k])/(xs[k+1]-xs[k])
                bb = np.array([(1-t)**3, 3*(1-t)**2*t, 3*(1-t)*t*t, t**3])
                c = bb @ base[k][:, 1]
                co = np.array([bb @ v[k][:, 1] for v in basis])
                A.extend([np.r_[co, -T], np.r_[-co, -T]]); B.extend([H-c, -H+c])
            for k, bc in enumerate(base):
                for j in range(3):
                    c = bc[j+1, 1]-bc[j, 1]
                    co = np.array([v[k][j+1, 1]-v[k][j, 1] for v in basis])
                    A.append(np.r_[co, 0]); B.append(-c)
                for j in range(2):
                    c = bc[j+2,1]-2*bc[j+1,1]+bc[j,1]
                    co = np.array([v[k][j+2,1]-2*v[k][j+1,1]+v[k][j,1] for v in basis])
                    A.append(np.r_[co, 0]); B.append(-c)
            lp = linprog([0]*ninner+[1], A_ub=A, b_ub=B,
                         bounds=[(None, None)]*ninner+[(0, 1)], method='highs')
            if not lp.success:
                continue
            hs = np.r_[h[0], lp.x[:-1], h[-1]]
            ss, recipe = catfix_segments(xs, hs)
            ok, ck = float_checks(ss, q, h)
            if ok:
                candidates.append((ck['max_ratio_2percent'], inds, hs, ss, recipe, ck))
        if candidates:
            _, inds, hs, ss, recipe, ck = min(candidates, key=lambda z: (z[0], z[1]))
            return ss, {'method': 'CATFIX_FEW_SUPPORT_NATURAL_C2_MONOTONE_2PERCENT',
                        'CATFIX_call': recipe, 'support_indices': inds,
                        'calculated_supports_not_table_changes': [
                            {'Q': float(q[i]), 'H_curve': float(v), 'H_selected_table': int(h[i])}
                            for i, v in zip(inds, hs)], 'fewest_supports_in_tested_grid_class': ninner+2,
                        'not_global_complexity_minimum': True, 'chosen_design_concave_natural_C2_not_universal_gate':True, 'unused_diagnostics': diagnostics}
    raise AssertionError('No bounded CATFIX natural C2 fit for this row at 2%')

numeric_functions_sources.float_checks:
def float_checks(segs, q, h):
    ratios, ders, joins, inflections = [], [], [], []
    for s in segs:
        w = s[-1, 0] - s[0, 0]
        if w <= 0 or np.max(abs(s[:, 0] - np.linspace(s[0, 0], s[-1, 0], 4))) > 1e-9:
            return False, {'reason': 'Q controls not affine'}
        d = 3 * np.diff(s[:, 1]) / w
        p = [d[0], 2 * (d[1] - d[0]), d[0] - 2*d[1] + d[2]]
        tt = [0., 1.]
        if abs(p[2]) > 1e-14:
            t = -p[1] / (2*p[2])
            if 0 < t < 1:
                tt.append(t)
        ders.append(float(max(np.polynomial.polynomial.polyval(tt, p))))
        d2 = 6*np.diff(s[:,1], n=2)/w**2
        inflections.append(bool(min(d2)<-1e-8 and max(d2)>1e-8))
    for Q, H in zip(q, h):
        s = next(z for z in segs if z[0, 0]-1e-10 <= Q <= z[-1, 0]+1e-10)
        t = (Q-s[0, 0])/(s[-1, 0]-s[0, 0])
        v = np.array([(1-t)**3, 3*(1-t)**2*t, 3*(1-t)*t*t, t**3]) @ s[:, 1]
        ratios.append(float(abs(v-H)/max(1., H*.02)))
    for a, b in zip(segs, segs[1:]):
        wa, wb = a[-1, 0]-a[0, 0], b[-1, 0]-b[0, 0]
        joins.append(max(float(np.max(abs(a[-1]-b[0]))),
                         abs(3*(a[3, 1]-a[2, 1])/wa-3*(b[1, 1]-b[0, 1])/wb),
                         abs(6*(a[3, 1]-2*a[2, 1]+a[1, 1])/wa**2-6*(b[2, 1]-2*b[1, 1]+b[0, 1])/wb**2)))
    end = max(abs(segs[0][0, 0]-q[0]), abs(segs[0][0, 1]-h[0]),
              abs(segs[-1][-1, 0]-q[-1]), abs(segs[-1][-1, 1]-h[-1]))
    checks = {'max_ratio_2percent': max(ratios), 'max_dHdQ': max(ders),
              'max_join_residual': max(joins, default=0.), 'end_residual': float(end),
              'significant_inflection_segments': [i for i,v in enumerate(inflections) if v]}
    return max(ratios) <= 1+1e-12 and max(ders) < 0 and max(joins, default=0.) < 1e-8 and end < 1e-9, checks

numeric_functions_sources.catfix_segments:
def catfix_segments(q, h, method='spline', tol=None):
    ch = catfix_charts.Chart(1, 0, 1, 0)
    path = ch.smooth_path(list(zip(q, h)), method=method, tol=tol)
    assert path[0][0] == 'm'
    cur, segs = path[0][1][0], []
    for op, pts in path[1:]:
        assert op == 'c'
        segs.append(np.array([cur, *pts], dtype=float))
        cur = pts[-1]
    return segs, {'public_API': 'catfix.charts.Chart(1,0,1,0).smooth_path',
                  'method': ch.last_method, 'last_fit': ch.last_fit}

numeric_functions_sources.finite:
def finite(v):
    # Float to shortest decimal once, then serialize 20 finite decimal places.
    v = v if isinstance(v, F) else F(str(float(v)))
    with localcontext() as c:
        c.prec = 80
        return format((Decimal(v.numerator) / Decimal(v.denominator)).quantize(Decimal('1e-20')), 'f')

