def extrema2(p):
    tt = [F(0), F(1)]
    if len(p) == 3 and p[2] != 0:
        t = -p[1]/(2*p[2])
        if 0 < t < 1:
            tt.append(t)
    vv = [ev(p, t) for t in tt]
    return tt, min(vv), max(vv)
